import sys
from collections import Counter

def is_valid_date(d, m, y):
    if y < 2013 or y > 2015:
        return False
    if m < 1 or m > 12:
        return False
    if d < 1:
        return False
    if m in {1, 3, 5, 7, 8, 10, 12} and d > 31:
        return False
    if m in {4, 6, 9, 11} and d > 30:
        return False
    if m == 2 and d > 28:
        return False
    return True

prophesy = sys.stdin.read().strip()
date_count = Counter(prophesy[i:i+10] for i in range(len(prophesy) - 9))
valid_dates = {date: count for date, count in date_count.items() if is_valid_date(int(date[:2]), int(date[3:5]), int(date[6:]))}
apocalypse_date = max(valid_dates, key=valid_dates.get)
print(apocalypse_date)
